#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>

using namespace std;

const int64_t mod = 998244353;
const int N = 5000;

vector<vector<int>> factor(N + 1);
vector<int64_t> primes;

int64_t comb(int m, int n) {
    int64_t res = 1;
    vector<int> fnm = factor[n];
    for (int i = 0; i < (int)factor[m].size(); i++) {
        fnm[i] += factor[m][i];
    }
    for (int w = 1; w <= m; w++) {
        int64_t r = 1;
        for (int i = 0; i < (int)primes.size(); i++) {
            int64_t p = primes[i];
            int pw = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i];
            while (pw > 0) {
                if (pw & 1) {
                    r = r * p % mod;
                }
                p = p * p % mod;
                pw >>= 1;
            }
        }
        res += r;
    }
    return res % mod;
}

int main() {
    int abc[3];
    cin >> abc[0] >> abc[1] >> abc[2];
    sort(abc, abc + 3);

    vector<bool> sieve(N + 1, false);
    sieve[0] = true;
    sieve[1] = true;
    for (int p = 2; p <= N; p++) {
        if (!sieve[p]) {
            primes.push_back(p);
            for (int q = p * p; q <= N; q += p) {
                sieve[q] = true;
            }
        }
    }

    for (int j = 0; j <= N; j++) {
        factor[j].resize(primes.size(), 0);
    }

    for (int i = 0; i < (int)primes.size(); i++) {
        int64_t p = primes[i];
        for (int64_t pp = p; pp <= N; pp *= p) {
            for (int j = (int)pp; j <= N; j += (int)pp) {
                factor[j][i]++;
            }
        }
    }

    vector<int> a = factor[0];
    for (int j = 1; j <= N; j++) {
        for (int i = 0; i < (int)a.size(); i++) {
            factor[j][i] += a[i];
        }
        a = factor[j];
    }

    int64_t result = comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % mod * comb(abc[1], abc[2]) % mod;
    cout << result << endl;

    return 0;
}
